import numpy as np, json
def transform(g):
    a=np.array(g); out=np.zeros_like(a)
    comps=[]; seen=np.zeros_like(a,bool)
    for i in range(a.shape[0]):
        for j in range(a.shape[1]):
            if a[i,j] and not seen[i,j]:
                c=a[i,j]; st=[(i,j)]; cells=[]; seen[i,j]=True
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<a.shape[0] and 0<=nx<a.shape[1] and a[ny,nx]==c and not seen[ny,nx]:
                            seen[ny,nx]=True; st.append((ny,nx))
                comps.append((c,cells))
    anchor=min(y for c,cells in comps if c==8 for y,x in cells)
    for c,cells in comps:
        top=min(y for y,x in cells)
        ys=[y for y,x in cells]; xs=[x for y,x in cells]
        if len(set(ys))==1:
            body=cells; x0=x1=None  # cap only? treat as body
        else:
            body=[(y,x) for y,x in cells if y!=top]
        bx0=min(x for y,x in body); bx1=max(x for y,x in body)
        cap=[x for y,x in cells if y==top]
        # center cap within body bbox
        span=bx1-bx0+1; off=(span-len(cap))//2
        newcap=[bx0+off+k for k in range(len(cap))]
        dy=anchor-top
        for y,x in body: out[y+dy,x]=c
        for k,x in enumerate(newcap): out[top+dy,x]=c
    return out.tolist()
